import { LinkCard } from '@refy-design/web';
import type { ComponentProps } from 'react';
const photos = {
  coverNeon: 'https://refy.design/demo/capa-neon.webp',
};
export function Example() {
  const args: Pick<
    ComponentProps<typeof LinkCard>,
    'href' | 'title' | 'description' | 'image'
  > = {
    href: 'https://refy.design/docs',
    title: 'Getting started with refy',
    description:
      'Install the package, wrap the app in the provider and change the whole look with one theme file.',
    image: photos.coverNeon,
  };
  return <LinkCard {...args} />;
}

